fn stable_hash(value: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    value.hash(&mut hasher);
    hasher.finish()
}

fn cache_namespace_for_token(token: &str) -> String {
    format!("{:x}", stable_hash(token))
}

